void install_tiles(void) {
    InstallTileSetAt((const unsigned short (*)[8])field_tiles, 8, T_FIELD);
    InstallTileSetAt((const unsigned short (*)[8])ice_tiles, 32, T_ICE);
    InstallTileSetAt((const unsigned short (*)[8])gem_tiles, 32, T_GEM);
    InstallTileSetAt((const unsigned short (*)[8])shat_tiles, 64, T_SHAT);
    InstallTileSetAt((const unsigned short (*)[8])edge_tiles, 64, T_EDGE);
    InstallTileSetAt((const unsigned short (*)[8])peng_tiles, 256, T_PENG);
    InstallTileSetAt((const unsigned short (*)[8])bee_tiles, 64, T_BEE);
    InstallTileSetAt((const unsigned short (*)[8])orca_tiles, 64, T_ORCA);
    InstallTileSetAt((const unsigned short (*)[8])kana_tiles, 216, T_KANA);
    InstallTileSetAt((const unsigned short (*)[8])title_tiles, 96, T_TITLE);
}

/* Banked over the kana block for the duration of an
 * intermission. install_tiles() restores the font. */
/* Banked over the title logo - it is only ever on screen at
 * the title. install_title_tiles() puts it back. */
void install_tropic_tiles(void) {
    InstallTileSetAt((const unsigned short (*)[8])tropic_tiles, 56, T_TRUNK);
}

void install_title_tiles(void) {
    InstallTileSetAt((const unsigned short (*)[8])title_tiles, 96, T_TITLE);
}

void install_inter_tiles(void) {
    InstallTileSetAt((const unsigned short (*)[8])inter_tiles, 168, T_INTER);
}
